section.markdown:
Billy l'ogre protège son camp derrière une palissade de vingt pieux. Avec ce qui a été vu
jusqu'ici, chaque pieu demande sa ligne :

```js
fill(110, 80, 50);
rect(0, 400, 20, 120);
rect(40, 400, 20, 120);
rect(80, 400, 20, 120);
// … dix-sept lignes de plus
```

Les vingt lignes ne diffèrent que par un nombre, qui augmente de 40 à chaque fois. La
boucle écrit la ligne une seule fois et la fait répéter :

section.sketch:
async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerBilly(400, 500, 250);

  fill(110, 80, 50);
  for (let i = 0; i < 20; i = i + 1) {
    rect(i * 40, 400, 20, 120);
  }
}

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerBilly(400, 500, 250);

  fill(110, 80, 50);
  for (let i = 0; i < 20; i = i + 1) {
    rect(i * 40, 400 - i * 5, 20, 120 + i * 5);
  }
}

let vieBilly = 10;

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);
  dessinerRaoul(250, 500, 120);
  dessinerBilly(600, 500, 250);

  fill(200, 30, 40);
  for (let i = 0; i < vieBilly; i = i + 1) {
    circle(470 + i * 30, 120, 20);
  }
}

function mousePressed() {
  vieBilly = vieBilly - 1;
}

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(20);

  for (let colonne = 0; colonne < 10; colonne = colonne + 1) {
    for (let rang = 0; rang < 5; rang = rang + 1) {
      dessinerRaoul(130 + colonne * 60, 170 + rang * 80, 40);
    }
  }
}
